n, *a = map(int, open(0).read().split())
left = [1] * n
right = [1] * n

# Fill the left list with the longest increasing sequence ending at each position
for i in range(1, n):
    if a[i] > a[i - 1]:
        left[i] = left[i - 1] + 1

# Fill the right list with the longest increasing sequence starting at each position
for i in range(n - 2, -1, -1):
    if a[i] > a[i + 1]:
        right[i] = right[i + 1] + 1

# Calculate the maximum Pyramid Sequence size
max_pyramid_size = 0
for i in range(n):
    max_pyramid_size = max(max_pyramid_size, left[i] + right[i] - 1)

print(max_pyramid_size)
